### Client Setup (React Component)
* Import `useUIStream` from `@json-render/react`.
* Point the hook to your backend API route.
* Pass the resulting live `spec` directly into the `<Renderer>` component to display values as they stream.

```tsx
'use client';
import { useUIStream } from '@json-render/react';
import { Renderer } from '@json-render/react';
import { registry } from '@/lib/registry';

export function Page() {
  const { spec, isStreaming, send } = useUIStream({
    api: '/api/generate',
  });

  return (
    <>
      <button onClick={() => send('Show a revenue chart')}>Generate</button>
      <Renderer spec={spec} registry={registry} loading={isStreaming} />
