          }
        }
      }
    },

    "item_data": {
      "type": "Column",
      "props": { "gap": "xs" },
      "children": ["data_field"]
    },
    "data_field": {
      "type": "Text",
      "repeat": {
        "bind": { "$entries": "item.data" },
        "as": "entry",
        "key": "entry.key"
      },
      "props": {
        "content": {
          "$template": "{{entry.key}}: {{entry.value}}"
        },
        "variant": "body2",
        "color": "muted"
      }
    },

    "item_actions": {
      "type": "Row",
      "props": { "gap": "sm" },
      "children": ["action_button"]
    },
    "action_button": {
      "type": "Button",
      "repeat": {
        "bind": "item.actions",
        "as": "action_name"
      },
      "props": {
        "label": { "$bind": "action_name" },
        "variant": "outline",
        "size": "sm"
      },
      "on": {
        "click": {
          "action": "dbus.call",
          "payload": {
            "path": { "$bind": "item.dbus_path" },
