/**
 * json-render Component Catalog for TchedRouter
 * Maps available shadcn/ui components for LLM-driven UI generation
 */
import { z } from 'zod';

// Component prop schemas
const CardProps = z.object({
  title: z.string().optional(),
  subtitle: z.string().optional(),
  className: z.string().optional(),
});

const BadgeProps = z.object({
  label: z.string(),
  variant: z.enum(['default', 'secondary', 'destructive', 'outline']).optional(),
  className: z.string().optional(),
});

const ButtonProps = z.object({
  label: z.string(),
  variant: z.enum(['default', 'destructive', 'outline', 'secondary', 'ghost', 'link']).optional(),
  size: z.enum(['default', 'sm', 'lg', 'icon']).optional(),
  disabled: z.boolean().optional(),
  className: z.string().optional(),
});

const TextProps = z.object({
  content: z.string(),
  variant: z.enum(['h1', 'h2', 'h3', 'h4', 'p', 'lead', 'large', 'small', 'muted']).optional(),
  className: z.string().optional(),
});

const RowProps = z.object({
  gap: z.enum(['none', 'xs', 'sm', 'md', 'lg']).optional(),
  justify: z.enum(['start', 'center', 'end', 'between', 'around']).optional(),
  align: z.enum(['start', 'center', 'end', 'stretch']).optional(),
  className: z.string().optional(),
});

const ColumnProps = z.object({
  gap: z.enum(['none', 'xs', 'sm', 'md', 'lg']).optional(),
  className: z.string().optional(),
});

const MetricProps = z.object({
  label: z.string(),
  value: z.union([z.string(), z.number()]),
  trend: z.enum(['up', 'down', 'flat']).optional(),
  format: z.enum(['number', 'percent', 'currency', 'bytes']).optional(),
  className: z.string().optional(),
});

const ProgressProps = z.object({
  value: z.number(),
  max: z.number().optional(),
  className: z.string().optional(),
});

const SeparatorProps = z.object({
  orientation: z.enum(['horizontal', 'vertical']).optional(),
  className: z.string().optional(),
});

const AlertProps = z.object({
  title: z.string().optional(),
  description: z.string(),
  variant: z.enum(['default', 'destructive']).optional(),
  className: z.string().optional(),
});

const InputProps = z.object({
  placeholder: z.string().optional(),
  type: z.enum(['text', 'password', 'email', 'number']).optional(),
  disabled: z.boolean().optional(),
  className: z.string().optional(),
});

const ScrollAreaProps = z.object({
  className: z.string().optional(),
  maxHeight: z.string().optional(),
});

// Export catalog definition for LLM system prompt
export const catalogDefinition = {
  Card: {
    description: 'Container with optional title/subtitle, supports children',
    props: CardProps,
    children: true,
  },
  Badge: {
    description: 'Small status indicator label',
    props: BadgeProps,
    children: false,
  },
  Button: {
    description: 'Clickable action button',
    props: ButtonProps,
    children: false,
    events: ['click'],
  },
  Text: {
    description: 'Typography element for text content',
    props: TextProps,
    children: false,
  },
  Row: {
    description: 'Horizontal flex container',
    props: RowProps,
    children: true,
  },
  Column: {
    description: 'Vertical flex container',
    props: ColumnProps,
    children: true,
  },
  Metric: {
    description: 'Key-value display with optional trend indicator',
    props: MetricProps,
    children: false,
  },
  Progress: {
    description: 'Progress bar indicator',
    props: ProgressProps,
    children: false,
  },
  Separator: {
    description: 'Visual divider line',
    props: SeparatorProps,
    children: false,
  },
  Alert: {
    description: 'Notification/alert message box',
    props: AlertProps,
    children: false,
  },
  Input: {
    description: 'Text input field with two-way binding',
    props: InputProps,
    children: false,
    events: ['change'],
  },
  ScrollArea: {
    description: 'Scrollable container',
    props: ScrollAreaProps,
    children: true,
  },
} as const;

// Type exports
export type CatalogComponents = typeof catalogDefinition;
export type ComponentName = keyof CatalogComponents;

/**
 * json-render Component Registry
 * Maps catalog components to shadcn/ui implementations
 */
import React from 'react';
import { Card, CardHeader, CardTitle, CardDescription, CardContent } from '@/components/ui/card';
import { Badge } from '@/components/ui/badge';
import { Button } from '@/components/ui/button';
import { Progress } from '@/components/ui/progress';
import { Separator } from '@/components/ui/separator';
import { Alert, AlertTitle, AlertDescription } from '@/components/ui/alert';
import { Input } from '@/components/ui/input';
import { ScrollArea } from '@/components/ui/scroll-area';
import { cn } from '@/lib/utils';
import { TrendingUp, TrendingDown, Minus } from 'lucide-react';
import type { BaseComponentProps } from '@json-render/react';

// Gap utilities
const gapClasses = {
  none: 'gap-0',
  xs: 'gap-1',
  sm: 'gap-2',
  md: 'gap-4',
  lg: 'gap-6',
};

const justifyClasses = {
  start: 'justify-start',
  center: 'justify-center',
  end: 'justify-end',
  between: 'justify-between',
  around: 'justify-around',
};

const alignClasses = {
  start: 'items-start',
  center: 'items-center',
  end: 'items-end',
  stretch: 'items-stretch',
};

// Text variant classes
const textVariants = {
  h1: 'scroll-m-20 text-4xl font-extrabold tracking-tight lg:text-5xl',
  h2: 'scroll-m-20 text-3xl font-semibold tracking-tight',
  h3: 'scroll-m-20 text-2xl font-semibold tracking-tight',
  h4: 'scroll-m-20 text-xl font-semibold tracking-tight',
  p: 'leading-7',
  lead: 'text-xl text-muted-foreground',
  large: 'text-lg font-semibold',
  small: 'text-sm font-medium leading-none',
  muted: 'text-sm text-muted-foreground',
};

// Component implementations
export const registry = {
  Card: ({ props, children }: BaseComponentProps<{ title?: string; subtitle?: string; className?: string }>) => (
    <Card className={props.className}>
      {(props.title || props.subtitle) && (
        <CardHeader>
          {props.title && <CardTitle>{props.title}</CardTitle>}
          {props.subtitle && <CardDescription>{props.subtitle}</CardDescription>}
        </CardHeader>
      )}
      <CardContent>{children}</CardContent>
    </Card>
  ),

  Badge: ({ props }: BaseComponentProps<{ label: string; variant?: 'default' | 'secondary' | 'destructive' | 'outline'; className?: string }>) => (
    <Badge variant={props.variant} className={props.className}>
      {props.label}
    </Badge>
  ),

  Button: ({ props, emit }: BaseComponentProps<{ label: string; variant?: 'default' | 'destructive' | 'outline' | 'secondary' | 'ghost' | 'link'; size?: 'default' | 'sm' | 'lg' | 'icon'; disabled?: boolean; className?: string }>) => (
    <Button
      variant={props.variant}
      size={props.size}
      disabled={props.disabled}
      className={props.className}
      onClick={() => emit('click')}
    >
      {props.label}
    </Button>
  ),

  Text: ({ props }: BaseComponentProps<{ content: string; variant?: keyof typeof textVariants; className?: string }>) => {
    const variant = props.variant || 'p';
    const Tag = variant.startsWith('h') ? (variant as 'h1' | 'h2' | 'h3' | 'h4') : 'p';
    return (
      <Tag className={cn(textVariants[variant], props.className)}>
        {props.content}
      </Tag>
    );
  },

  Row: ({ props, children }: BaseComponentProps<{ gap?: keyof typeof gapClasses; justify?: keyof typeof justifyClasses; align?: keyof typeof alignClasses; className?: string }>) => (
    <div
      className={cn(
        'flex flex-row',
        gapClasses[props.gap || 'md'],
        justifyClasses[props.justify || 'start'],
        alignClasses[props.align || 'center'],
        props.className
      )}
    >
      {children}
    </div>
  ),

  Column: ({ props, children }: BaseComponentProps<{ gap?: keyof typeof gapClasses; className?: string }>) => (
    <div className={cn('flex flex-col', gapClasses[props.gap || 'md'], props.className)}>
      {children}
    </div>
  ),

  Metric: ({ props }: BaseComponentProps<{ label: string; value: string | number; trend?: 'up' | 'down' | 'flat'; format?: 'number' | 'percent' | 'currency' | 'bytes'; className?: string }>) => {
    const formatValue = (val: string | number, fmt?: string) => {
      if (typeof val === 'string') return val;
      switch (fmt) {
        case 'percent': return `${val}%`;
        case 'currency': return `$${val.toLocaleString()}`;
        case 'bytes': {
          const units = ['B', 'KB', 'MB', 'GB', 'TB'];
          let size = val;
          let unitIndex = 0;
          while (size >= 1024 && unitIndex < units.length - 1) {
            size /= 1024;
            unitIndex++;
          }
          return `${size.toFixed(1)} ${units[unitIndex]}`;
        }
        default: return val.toLocaleString();
      }
    };

    const TrendIcon = props.trend === 'up' ? TrendingUp : props.trend === 'down' ? TrendingDown : Minus;
    const trendColor = props.trend === 'up' ? 'text-green-500' : props.trend === 'down' ? 'text-red-500' : 'text-muted-foreground';

    return (
      <div className={cn('flex flex-col', props.className)}>
        <span className="text-sm text-muted-foreground">{props.label}</span>
        <div className="flex items-center gap-2">
          <span className="text-2xl font-bold">{formatValue(props.value, props.format)}</span>
          {props.trend && <TrendIcon className={cn('h-4 w-4', trendColor)} />}
        </div>
      </div>
    );
  },

  Progress: ({ props }: BaseComponentProps<{ value: number; max?: number; className?: string }>) => (
    <Progress value={props.value} max={props.max} className={props.className} />
  ),

  Separator: ({ props }: BaseComponentProps<{ orientation?: 'horizontal' | 'vertical'; className?: string }>) => (
    <Separator orientation={props.orientation} className={props.className} />
  ),

  Alert: ({ props }: BaseComponentProps<{ title?: string; description: string; variant?: 'default' | 'destructive'; className?: string }>) => (
    <Alert variant={props.variant} className={props.className}>
      {props.title && <AlertTitle>{props.title}</AlertTitle>}
      <AlertDescription>{props.description}</AlertDescription>
    </Alert>
  ),

  Input: ({ props, emit, bindings }: BaseComponentProps<{ placeholder?: string; type?: string; disabled?: boolean; className?: string; value?: string }>) => (
    <Input
      type={props.type || 'text'}
      placeholder={props.placeholder}
      disabled={props.disabled}
      className={props.className}
      value={props.value || ''}
      onChange={(e) => emit('change')}
    />
  ),

  ScrollArea: ({ props, children }: BaseComponentProps<{ className?: string; maxHeight?: string }>) => (
    <ScrollArea className={props.className} style={{ maxHeight: props.maxHeight }}>
      {children}
    </ScrollArea>
  ),
};

export type Registry = typeof registry;

/**
 * JsonRenderView - Main renderer component for json-render specs
 * Renders streamed UI specs using shadcn/ui components
 */
import React from 'react';
import { Renderer, JSONUIProvider, type Spec } from '@json-render/react';
import { registry } from './registry';
import { Loader2 } from 'lucide-react';

interface JsonRenderViewProps {
  /** The UI spec to render */
  spec: Spec | null;
  /** Whether spec is currently streaming */
  loading?: boolean;
  /** Initial state for bindings */
  state?: Record<string, unknown>;
  /** Callback when state changes */
  onStateChange?: (changes: Array<{ path: string; value: unknown }>) => void;
  /** Action handler for button clicks, etc. */
  onAction?: (actionName: string, params?: Record<string, unknown>) => void;
  /** Custom class name */
  className?: string;
}

/**
 * Fallback component for unknown element types
 */
const FallbackComponent = ({ element }: { element: { type: string; props?: Record<string, unknown> } }) => (
  <div className="p-2 border border-dashed border-yellow-500 rounded bg-yellow-50 text-yellow-800 text-sm">
    Unknown component: <code>{element.type}</code>
  </div>
);

/**
 * Loading indicator shown while streaming
 */
const StreamingIndicator = () => (
  <div className="flex items-center gap-2 text-sm text-muted-foreground">
    <Loader2 className="h-4 w-4 animate-spin" />
    <span>Generating UI...</span>
  </div>
);

/**
 * Empty state when no spec is provided
 */
const EmptyState = () => (
  <div className="flex items-center justify-center p-8 text-muted-foreground">
    No UI specification to render
  </div>
);

export function JsonRenderView({
  spec,
  loading = false,
  state = {},
  onStateChange,
  onAction,
  className,
}: JsonRenderViewProps) {
  // Convert action handler to handlers map
  const handlers = React.useMemo(() => {
    if (!onAction) return {};
    return {
      // Generic action dispatcher
      dispatch: async (params: Record<string, unknown>) => {
        onAction('dispatch', params);
      },
      'dbus.call': async (params: Record<string, unknown>) => {
        onAction('dbus.call', params);
      },
      'grpc.call': async (params: Record<string, unknown>) => {
        onAction('grpc.call', params);
      },
      navigate: async (params: Record<string, unknown>) => {
        onAction('navigate', params);
      },
    };
  }, [onAction]);

  // Show loading state
  if (!spec && loading) {
    return (
      <div className={className}>
        <StreamingIndicator />
      </div>
    );
  }

  // Show empty state
  if (!spec) {
    return (
      <div className={className}>
        <EmptyState />
      </div>
    );
  }

  return (
    <div className={className}>
      {loading && <StreamingIndicator />}
      <JSONUIProvider
        registry={registry}
        initialState={state}
        handlers={handlers}
        onStateChange={onStateChange}
      >
        <Renderer
          spec={spec}
          registry={registry}
          loading={loading}
          fallback={FallbackComponent}
        />
      </JSONUIProvider>
    </div>
  );
}

export default JsonRenderView;

/**
 * useSpecStream - Hook for streaming json-render specs
 * Wraps @json-render/react's useUIStream with project-specific defaults
 */
import { useUIStream, type Spec } from '@json-render/react';
import { useCallback, useState } from 'react';

interface UseSpecStreamOptions {
  /** API endpoint for spec generation */
  endpoint: string;
  /** Callback when generation completes */
  onComplete?: (spec: Spec) => void;
  /** Callback on error */
  onError?: (error: Error) => void;
}

interface UseSpecStreamReturn {
  /** Current compiled spec */
  spec: Spec | null;
  /** Whether currently streaming */
  isStreaming: boolean;
  /** Error if any */
  error: Error | null;
  /** Raw JSONL lines received */
  rawLines: string[];
  /** Send a prompt to generate UI */
  generate: (prompt: string, context?: Record<string, unknown>) => Promise<void>;
  /** Clear current spec and reset */
  clear: () => void;
  /** Abort current generation */
  abort: () => void;
}

/**
 * Hook for streaming json-render UI specifications.
 * 
 * @example
 * ```tsx
 * const { spec, isStreaming, generate } = useSpecStream({
 *   endpoint: '/api/generate-ui',
 * });
 * 
 * // Generate UI from prompt
 * await generate('Show network status dashboard');
 * 
 * // Render the result
 * <JsonRenderView spec={spec} loading={isStreaming} />
 * ```
 */
export function useSpecStream({
  endpoint,
  onComplete,
  onError,
}: UseSpecStreamOptions): UseSpecStreamReturn {
  const [abortController, setAbortController] = useState<AbortController | null>(null);

  const {
    spec,
    isStreaming,
    error,
    rawLines,
    send,
    clear: clearSpec,
  } = useUIStream({
    api: endpoint,
    onComplete,
    onError,
  });

  const generate = useCallback(async (prompt: string, context?: Record<string, unknown>) => {
    // Create new abort controller for this request
    const controller = new AbortController();
    setAbortController(controller);

    try {
      await send(prompt, context);
    } finally {
      setAbortController(null);
    }
  }, [send]);

  const abort = useCallback(() => {
    if (abortController) {
      abortController.abort();
      setAbortController(null);
    }
  }, [abortController]);

  const clear = useCallback(() => {
    abort();
    clearSpec();
  }, [abort, clearSpec]);

  return {
    spec,
    isStreaming,
    error,
    rawLines,
    generate,
    clear,
    abort,
  };
}

export default useSpecStream;

/**
 * json-render integration exports
 */
export { JsonRenderView } from './JsonRenderView';
export { registry } from './registry';
export { catalogDefinition, type CatalogComponents, type ComponentName } from './catalog';

