/**
 * json-render Component Registry
 * 
 * Uses defineRegistry from @json-render/react to map catalog
 * components to real shadcn/ui implementations.
 */
import React from 'react';
import { defineRegistry } from '@json-render/react';
import { Card, CardHeader, CardTitle, CardDescription, CardContent } from '@/components/ui/card';
import { Badge } from '@/components/ui/badge';
import { Button } from '@/components/ui/button';
import { Progress } from '@/components/ui/progress';
import { Separator } from '@/components/ui/separator';
import { Alert, AlertTitle, AlertDescription } from '@/components/ui/alert';
import { Input } from '@/components/ui/input';
import { ScrollArea } from '@/components/ui/scroll-area';
import { cn } from '@/lib/utils';
import { TrendingUp, TrendingDown, Minus, Activity, Circle } from 'lucide-react';
import { catalog } from './catalog';

// Gap utilities
const gapClasses = {
  none: 'gap-0',
  xs: 'gap-1',
  sm: 'gap-2',
  md: 'gap-4',
  lg: 'gap-6',
};

const justifyClasses = {
  start: 'justify-start',
  center: 'justify-center',
  end: 'justify-end',
  between: 'justify-between',
  around: 'justify-around',
};

const alignClasses = {
  start: 'items-start',
  center: 'items-center',
  end: 'items-end',
  stretch: 'items-stretch',
};

// Text variant classes
const textVariants = {
  h1: 'scroll-m-20 text-4xl font-extrabold tracking-tight lg:text-5xl',
  h2: 'scroll-m-20 text-3xl font-semibold tracking-tight',
  h3: 'scroll-m-20 text-2xl font-semibold tracking-tight',
  h4: 'scroll-m-20 text-xl font-semibold tracking-tight',
  p: 'leading-7',
  lead: 'text-xl text-muted-foreground',
  large: 'text-lg font-semibold',
  small: 'text-sm font-medium leading-none',
  muted: 'text-sm text-muted-foreground',
};

// Status colors
const statusColors = {
  running: 'text-green-500',
  active: 'bg-green-500',
  stopped: 'text-muted-foreground',
  inactive: 'bg-muted-foreground',
  error: 'text-destructive',
  pending: 'bg-yellow-500',
  unknown: 'text-muted-foreground',
};

// Format value helper
const formatValue = (val: string | number, fmt?: string) => {
  if (typeof val === 'string') return val;
  switch (fmt) {
    case 'percent': return `${val}%`;
    case 'currency': return `$${val.toLocaleString()}`;
    case 'bytes': {
      const units = ['B', 'KB', 'MB', 'GB', 'TB'];
      let size = val;
      let unitIndex = 0;
      while (size >= 1024 && unitIndex < units.length - 1) {
        size /= 1024;
        unitIndex++;
      }
      return `${size.toFixed(1)} ${units[unitIndex]}`;
    }
    default: return val.toLocaleString();
  }
};

/**
 * Registry created with defineRegistry for type-safe component mapping.
 */
export const { registry } = defineRegistry(catalog, {
  components: {
    Card: ({ props, children }) => (
      <Card className={props.className}>
        {(props.title || props.subtitle) && (
          <CardHeader>
            {props.title && <CardTitle>{props.title}</CardTitle>}
            {props.subtitle && <CardDescription>{props.subtitle}</CardDescription>}
          </CardHeader>
        )}
        <CardContent>{children}</CardContent>
      </Card>
    ),

    Badge: ({ props }) => (
      <Badge variant={props.variant} className={props.className}>
        {props.label}
      </Badge>
    ),

    Button: ({ props, emit }) => (
      <Button
        variant={props.variant}
        size={props.size}
        disabled={props.disabled}
        className={props.className}
        onClick={() => emit('click')}
      >
        {props.label}
      </Button>
    ),

    Text: ({ props }) => {
      const variant = props.variant || 'p';
      const Tag = variant.startsWith('h') ? (variant as 'h1' | 'h2' | 'h3' | 'h4') : 'p';
      return (
        <Tag className={cn(textVariants[variant], props.className)}>
          {props.content}
        </Tag>
      );
    },

    Row: ({ props, children }) => (
      <div
        className={cn(
          'flex flex-row',
          gapClasses[props.gap || 'md'],
          justifyClasses[props.justify || 'start'],
          alignClasses[props.align || 'center'],
          props.className
        )}
      >
        {children}
      </div>
    ),

    Column: ({ props, children }) => (
      <div className={cn('flex flex-col', gapClasses[props.gap || 'md'], props.className)}>
        {children}
      </div>
    ),

    Metric: ({ props }) => {
      const TrendIcon = props.trend === 'up' ? TrendingUp : props.trend === 'down' ? TrendingDown : Minus;
      const trendColor = props.trend === 'up' ? 'text-green-500' : props.trend === 'down' ? 'text-red-500' : 'text-muted-foreground';

      return (
        <div className={cn('flex flex-col', props.className)}>
          <span className="text-sm text-muted-foreground">{props.label}</span>
          <div className="flex items-center gap-2">
            <span className="text-2xl font-bold">{formatValue(props.value, props.format)}</span>
            {props.trend && <TrendIcon className={cn('h-4 w-4', trendColor)} />}
          </div>
        </div>
      );
    },

    Progress: ({ props }) => (
      <Progress value={props.value} max={props.max} className={props.className} />
    ),

    Separator: ({ props }) => (
      <Separator orientation={props.orientation} className={props.className} />
    ),

    Alert: ({ props }) => (
      <Alert variant={props.variant} className={props.className}>
        {props.title && <AlertTitle>{props.title}</AlertTitle>}
        <AlertDescription>{props.description}</AlertDescription>
      </Alert>
    ),

    Input: ({ props, emit, bindings }) => (
      <Input
        type={props.type || 'text'}
        placeholder={props.placeholder}
        disabled={props.disabled}
        className={props.className}
        value={props.value || ''}
        onChange={() => emit('change')}
      />
    ),

    ScrollArea: ({ props, children }) => (
      <ScrollArea className={props.className} style={{ maxHeight: props.maxHeight }}>
        {children}
      </ScrollArea>
    ),

    // Plugin-specific components
    PluginCard: ({ props, children }) => {
      const statusIcon = {
        running: <Activity className="h-4 w-4 text-green-500 animate-pulse" />,
        stopped: <Circle className="h-4 w-4 text-muted-foreground" />,
        error: <Circle className="h-4 w-4 text-destructive" />,
        unknown: <Circle className="h-4 w-4 text-muted-foreground" />,
      };

      return (
        <Card className={props.className}>
          <CardHeader className="pb-2">
            <div className="flex items-center justify-between">
              <CardTitle className="text-lg font-mono">{props.pluginId}</CardTitle>
              {props.status && statusIcon[props.status]}
            </div>
          </CardHeader>
          <CardContent>{children}</CardContent>
        </Card>
      );
    },

    MetricGrid: ({ props, children }) => (
      <div
        className={cn(
          'grid gap-4',
          props.columns === 2 ? 'grid-cols-2' :
          props.columns === 3 ? 'grid-cols-3' :
          props.columns === 4 ? 'grid-cols-4' :
          'grid-cols-2 md:grid-cols-4',
          props.className
        )}
      >
        {children}
      </div>
    ),

    StatusBadge: ({ props }) => {
      const colorMap = {
        active: 'bg-green-500/20 text-green-600 border-green-500/50',
        inactive: 'bg-muted text-muted-foreground',
        pending: 'bg-yellow-500/20 text-yellow-600 border-yellow-500/50',
        error: 'bg-destructive/20 text-destructive border-destructive/50',
      };

      return (
        <span className={cn(
          'inline-flex items-center gap-1.5 px-2 py-0.5 rounded-full text-xs font-medium border',
          colorMap[props.status]
        )}>
          <span className={cn('h-1.5 w-1.5 rounded-full', statusColors[props.status])} />
          {props.label || props.status}
        </span>
      );
    },

    ActionGroup: ({ props, children }) => (
      <div className={cn('flex gap-2', props.className)}>
        {children}
      </div>
    ),
  },
});

export type Registry = typeof registry;

/**
 * PluginChatView - Chat interface with json-render UI extraction
 *
 * Uses useJsonRenderMessage from @json-render/react to extract specs
 * from AI SDK message parts, combined with streaming chat.
 */
import React, { useState, FormEvent, useRef, useEffect, useMemo, useCallback } from 'react';
import { useJsonRenderMessage, Renderer, JSONUIProvider, type DataPart } from '@json-render/react';
import { createSpecStreamCompiler, type Spec, buildUserPrompt } from '@json-render/core';
import { registry } from './registry';
import { catalog } from './catalog';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { ScrollArea } from '@/components/ui/scroll-area';
import { Badge } from '@/components/ui/badge';
import { cn } from '@/lib/utils';
import { Send, Loader2, RefreshCw, Bot, User, Sparkles, Code } from 'lucide-react';
import { streamChat } from '@/api/client';

// Plugin catalog for quick selection
const PLUGIN_CATALOG = [
  'adc', 'agentConfig', 'antigravity', 'snowball', 'btrfs',
  'cognitiveMcp', 'compactMcp', 'config', 'cron', 'ctlPlaneChatbot',
  'datastore', 'dnsresolver', 'embeddingModel', 'emqx', 'endpoint',
  'factory', 'fail2ban', 'freedesktop', 'fullSystem', 'gcloudAdc',
  'gemmaBrain', 'ghostbridge', 'hardware', 'hostRuntime', 'humanPrincipal',
  'identitySled', 'incus', 'jsonRender', 'keypair', 'keyring',
  'largeLanguageModel', 'login1', 'mailServer', 'mcp', 'memory',
  'net', 'netmaker', 'notebooklm', 'oci', 'openflow',
  'openflowObfuscation', 'oscalSubidRegistry', 'ovsdbBridge', 'packagekit', 'pcidecl',
  'persona', 'privacyRoutes', 'procfs', 'proxyServer', 'qdrant',
  'rovsCommands', 'rtnetlink', 'schemaRenderer', 'service', 'sessDecl',
  'sharedUnixSocket', 'software', 'tchedRouter', 'unixSocket', 'users',
  'webUi', 'wgOpdbus', 'wgcf', 'wireguard', 'workflows', 'xray',
] as const;

/**
 * Message with AI SDK compatible parts array
 */
interface ChatMessage {
  id: string;
  role: 'user' | 'assistant';
  content: string;
  /** AI SDK compatible parts array for useJsonRenderMessage */
  parts: DataPart[];
}

/**
 * Convert raw text content to DataPart array.
 * Attempts to extract json-render spec from code fences or raw JSON.
 */
function contentToParts(content: string): DataPart[] {
  const parts: DataPart[] = [];

  if (!content) return parts;

  // Try to find JSON spec in code fences
  const fenceMatch = content.match(/```(?:json)?\s*([\s\S]*?)```/);
  let specJson: string | null = null;
  let textContent = content;

  if (fenceMatch) {
    specJson = fenceMatch[1].trim();
    const fenceIndex = content.indexOf('```');
    textContent = content.slice(0, fenceIndex).trim();
  } else {
    // Try to find raw JSON object with spec structure
    const jsonMatch = content.match(/\{[\s\S]*"root"[\s\S]*"elements"[\s\S]*\}/);
    if (jsonMatch) {
      specJson = jsonMatch[0];
      const jsonIndex = content.indexOf(specJson);
      textContent = content.slice(0, jsonIndex).trim();
    }
  }

  // Add text part if present
  if (textContent) {
    parts.push({ type: 'text', text: textContent });
  }

  // Try to parse and add data part for spec
  if (specJson) {
    try {
      const parsed = JSON.parse(specJson);
      if (parsed && typeof parsed === 'object' && 'root' in parsed && 'elements' in parsed) {
        parts.push({ type: 'data', data: parsed });
      }
    } catch {
      // Try streaming compiler for partial JSON
      try {
        const compiler = createSpecStreamCompiler<Spec>();
        const { result } = compiler.push(specJson);
        if (result && 'root' in result && 'elements' in result) {
          parts.push({ type: 'data', data: result });
        }
      } catch {
        // Fall through - no valid spec
      }
    }
  }

  return parts;
}

/**
 * Component to render a single message with json-render extraction
 */
function MessageContent({ message }: { message: ChatMessage }) {
  // Use json-render's hook to extract spec from parts
  const { spec, text, hasSpec } = useJsonRenderMessage(message.parts);
  const [showRaw, setShowRaw] = useState(false);

  const handleAction = useCallback((actionName: string, params?: Record<string, unknown>) => {
    console.log('[PluginChatView] Action:', actionName, params);
  }, []);

  return (
    <div className="flex-1 space-y-3 min-w-0">
      {/* Text content */}
      {text && (
        <p className="text-sm whitespace-pre-wrap">{text}</p>
      )}

      {/* Rendered spec */}
      {hasSpec && spec && (
        <div className="space-y-2">
          <div className="flex items-center gap-2">
            <Badge variant="outline" className="text-xs">
              <Sparkles className="w-3 h-3 mr-1" />
              Generated UI
            </Badge>
            <Button
              variant="ghost"
              size="sm"
              className="h-6 px-2 text-xs"
              onClick={() => setShowRaw(!showRaw)}
            >
              <Code className="w-3 h-3 mr-1" />
              {showRaw ? 'Hide' : 'Show'} JSON
            </Button>
          </div>

          {showRaw ? (
            <pre className="p-3 bg-muted rounded-lg text-xs overflow-auto max-h-64">
              {JSON.stringify(spec, null, 2)}
            </pre>
          ) : (
            <div className="border rounded-lg p-4 bg-card">
              <JSONUIProvider
                registry={registry}
                handlers={{
                  dispatch: async (params) => handleAction('dispatch', params),
                }}
              >
                <Renderer spec={spec} />
              </JSONUIProvider>
            </div>
          )}
        </div>
      )}

      {/* Show raw content if no spec extracted */}
      {!hasSpec && !text && message.content && (
        <p className="text-sm whitespace-pre-wrap text-muted-foreground">
          {message.content}
        </p>
      )}
    </div>
  );
}

interface PluginChatViewProps {
  /** Initial plugin to focus on */
  initialPlugin?: string;
  /** Custom class name */
  className?: string;
}

export function PluginChatView({
  initialPlugin = 'tchedRouter',
  className,
}: PluginChatViewProps) {
  const [input, setInput] = useState('');
  const [selectedPlugin, setSelectedPlugin] = useState(initialPlugin);
  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const scrollRef = useRef<HTMLDivElement>(null);
  const abortRef = useRef<AbortController | null>(null);

  // Auto-scroll on new messages
  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [messages]);

  const handleSubmit = async (e: FormEvent) => {
    e.preventDefault();
    if (!input.trim() || isLoading) return;

    const userMessage: ChatMessage = {
      id: `user-${Date.now()}`,
      role: 'user',
      content: input,
      parts: [{ type: 'text', text: input }],
    };

    setMessages((prev) => [...prev, userMessage]);
    setInput('');
    setIsLoading(true);
    setError(null);

    // Create assistant message placeholder
    const assistantId = `assistant-${Date.now()}`;
    setMessages((prev) => [
      ...prev,
      { id: assistantId, role: 'assistant', content: '', parts: [] },
    ]);

    // Stream the response
    let fullContent = '';
    abortRef.current = streamChat(
      input,
      undefined,
      (chunk) => {
        fullContent += chunk;
        // Update message with accumulated content and parsed parts
        const parts = contentToParts(fullContent);
        setMessages((prev) =>
          prev.map((msg) =>
            msg.id === assistantId
              ? { ...msg, content: fullContent, parts }
              : msg
          )
        );
      },
      () => {
        setIsLoading(false);
        abortRef.current = null;
      }
    );
  };

  const handlePluginSelect = (plugin: string) => {
    setSelectedPlugin(plugin);

    // Build prompt using json-render's buildUserPrompt for proper catalog context
    const prompt = `Generate a json-render UI spec for the "${plugin}" plugin.

The spec should include:
- A PluginCard with the plugin ID and status
- A MetricGrid showing key metrics
- StatusBadge for current state
- ActionGroup with common operations

Use the available components: Card, Badge, Button, Text, Row, Column, Metric, Progress, Alert, PluginCard, MetricGrid, StatusBadge, ActionGroup.

Return a valid JSON spec with { root, elements } structure where:
- root: string key of the root element
- elements: Record<string, { type, props, children? }> mapping`;

    setInput(prompt);
  };

  const handleStop = () => {
    if (abortRef.current) {
      abortRef.current.abort();
      setIsLoading(false);
    }
  };

  const handleClear = () => {
    setMessages([]);
    setError(null);
  };

  return (
    <div className={cn('flex h-full', className)}>
      {/* Plugin sidebar */}
      <div className="w-48 border-r flex flex-col">
        <div className="p-3 border-b">
          <h3 className="font-semibold text-sm flex items-center gap-2">
            <Sparkles className="w-4 h-4" />
            Plugins
          </h3>
        </div>
        <ScrollArea className="flex-1">
          <div className="p-2 space-y-1">
            {PLUGIN_CATALOG.map((plugin) => (
              <Button
                key={plugin}
                variant={selectedPlugin === plugin ? 'secondary' : 'ghost'}
                size="sm"
                className="w-full justify-start text-xs font-mono h-7"
                onClick={() => handlePluginSelect(plugin)}
              >
                {plugin}
              </Button>
            ))}
          </div>
        </ScrollArea>
      </div>

      {/* Chat area */}
      <div className="flex-1 flex flex-col">
        {/* Header */}
        <div className="p-3 border-b flex items-center justify-between">
          <div className="flex items-center gap-2">
            <h2 className="font-semibold">Plugin UI Generator</h2>
            <Badge variant="outline" className="font-mono">
              {selectedPlugin}
            </Badge>
          </div>
          <Button
            variant="ghost"
            size="sm"
            onClick={handleClear}
            disabled={messages.length === 0}
          >
            <RefreshCw className="w-4 h-4" />
          </Button>
        </div>

        {/* Messages */}
        <ScrollArea ref={scrollRef} className="flex-1">
          {messages.length === 0 ? (
            <div className="flex flex-col items-center justify-center h-full p-8 text-muted-foreground">
              <Bot className="w-12 h-12 mb-4" />
              <p className="text-center mb-2">
                Select a plugin from the sidebar to generate a UI spec.
              </p>
              <p className="text-center text-sm">
                Uses <code className="text-xs bg-muted px-1 rounded">useJsonRenderMessage</code> for spec extraction.
              </p>
            </div>
          ) : (
            <div className="divide-y">
              {messages.map((message) => (
                <div
                  key={message.id}
                  className={cn(
                    'flex gap-3 p-4',
                    message.role === 'user' ? 'bg-muted/50' : 'bg-background'
                  )}
                >
                  <div
                    className={cn(
                      'flex-shrink-0 w-8 h-8 rounded-full flex items-center justify-center',
                      message.role === 'user'
                        ? 'bg-primary text-primary-foreground'
                        : 'bg-secondary'
                    )}
                  >
                    {message.role === 'user' ? (
                      <User className="w-4 h-4" />
                    ) : (
                      <Bot className="w-4 h-4" />
                    )}
                  </div>

                  {message.role === 'user' ? (
                    <div className="flex-1">
                      <p className="text-sm whitespace-pre-wrap">{message.content}</p>
                    </div>
                  ) : (
                    <MessageContent message={message} />
                  )}

                  {/* Show streaming indicator */}
                  {message.role === 'assistant' &&
                    !message.content &&
                    isLoading && (
                      <div className="flex items-center gap-2 text-muted-foreground">
                        <Loader2 className="w-4 h-4 animate-spin" />
                        <span className="text-sm">Generating...</span>
                      </div>
                    )}
                </div>
              ))}
            </div>
          )}
        </ScrollArea>

        {/* Error display */}
        {error && (
          <div className="p-3 bg-destructive/10 text-destructive text-sm">
            Error: {error}
          </div>
        )}

        {/* Input */}
        <form onSubmit={handleSubmit} className="p-3 border-t flex gap-2">
          <Input
            value={input}
            onChange={(e) => setInput(e.target.value)}
            placeholder={`Describe the UI you want for ${selectedPlugin}...`}
            disabled={isLoading}
            className="flex-1"
          />
          {isLoading ? (
            <Button type="button" variant="outline" onClick={handleStop}>
              Stop
            </Button>
          ) : (
            <Button type="submit" disabled={!input.trim()}>
              <Send className="w-4 h-4" />
            </Button>
          )}
        </form>
      </div>
    </div>
  );
}

export default PluginChatView;

