const handleSend = () => {
  if (!input.trim()) return;

  const newMessage: Message = {
    id: Date.now().toString(),
    senderName: "You",
    text: input,
    timestamp: new Date().toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" }),
    isCurrentUser: true,
  };

  setMessages((prev) => [...prev, newMessage]);
  setInput("");

  // Route based on selected mode
  if (mode === "local-echo") {
    // Local echo demo
    setTyping(["User 1"]);
    setTimeout(() => {
      const response: Message = {
        id: (Date.now() + 1).toString(),
        senderName: "User 1",
        text: `You said: "${input}"`,
        timestamp: new Date().toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" }),
        isCurrentUser: false,
      };
      setMessages((prev) => [...prev, response]);
      setTyping([]);
    }, 1000);
  } else if (mode === "zeroclaw") {
    // Call zeroclaw API
    setTyping(["Zeroclaw"]);
    const userMessage = input;
    fetch("http://127.0.0.1:8082/v1/chat/completions", {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        Authorization: `Bearer ${sessionStorage.getItem("opencode-api-key") || ""}`,
      },
      body: JSON.stringify({
        model: "gpt-4",
        messages: [{ role: "user", content: userMessage }],
        max_tokens: 256,
      }),
    })
      .then((res) => res.json())
      .then((data) => {
        const response: Message = {
          id: (Date.now() + 1).toString(),
          senderName: "Zeroclaw",
          text: data.choices?.[0]?.message?.content || "No response",
          timestamp: new Date().toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" }),
          isCurrentUser: false,
        };
        setMessages((prev) => [...prev, response]);
        setTyping([]);
      })
      .catch((err) => {
        console.error("Zeroclaw error:", err);
        const response: Message = {
          id: (Date.now() + 1).toString(),
          senderName: "Zeroclaw",
          text: `Error: ${err.message}`,
          timestamp: new Date().toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" }),
          isCurrentUser: false,
        };
        setMessages((prev) => [...prev, response]);
        setTyping([]);
      });
  } else if (mode === "chat-service") {
    // Call chat service
    setTyping(["Chat Service"]);
    // TODO: Implement gRPC call to 10.50.0.1:50053
    setTimeout(() => {
      const response: Message = {
        id: (Date.now() + 1).toString(),
        senderName: "Chat Service",
        text: "Chat service not yet connected",
        timestamp: new Date().toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" }),
        isCurrentUser: false,
      };
      setMessages((prev) => [...prev, response]);
      setTyping([]);
    }, 1000);
  }
};

