// Hand-written gRPC-Web client for ChatService
// Based on /srv/git/odbus/crates/op-chat/proto/chat.proto

import { createConnectTransport } from "@connectrpc/connect-web";
import { createClient } from "@connectrpc/connect";

// We'll use a simple fetch-based approach for grpc-web since full codegen is complex

export interface SendRequest {
  conversationId: string;
  uiMessages: Uint8Array; // JSON-encoded UIMessage[]
  personaId?: string;
  provider: string;
  model: string;
  resumeCursor?: bigint;
}

export interface ChatFrame {
  cursor: bigint;
  body:
    | { part: UIMessagePart }
    | { error: StreamError }
    | { heartbeat: Heartbeat }
    | { done: StreamDone }
    | { approval: ApprovalRequired };
}

export interface UIMessagePart {
  messageId: string;
  role: string;
  kind: string;
  payload: Uint8Array;
}

export interface StreamError {
  code: string;
  message: string;
  retryable: boolean;
  retryAfterMs?: number;
}

export interface Heartbeat {
  serverTimeMs: bigint;
}

export interface StreamDone {
  conversationId: string;
  totalParts: bigint;
}

